using System;

namespace YS.Knife.Operations
{
    [AttributeUsage(AttributeTargets.Method, AllowMultiple = false)]
    public class OperationAttribute : Attribute
    {
        public OperationAttribute(string id, string description) { Id = id; Description = description; }
        public string Id { get; }
        public string Description { get; }
    }
}

public interface ILabelService
{
    string QueryAll();

    [YS.Knife.Operations.OperationAttribute("create", "创建标签")]
    string Create(string name);

    [YS.Knife.Operations.OperationAttribute("delete", "删除标签")]
    string Delete(int id);
}

[YS.Knife.ExposeApi(typeof(ILabelService))]
public class TestController
{
}

