#pragma warning disable CS1591, CS1573
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
namespace 
{
    [ApiController]
    [Route("api/[controller]")]
    public class LabelController : ControllerBase
    {
        private readonly global::ILabelService iLabelService;
        public LabelController(global::ILabelService iLabelService)
        {
            this.iLabelService = iLabelService;
        }
        [Route("QueryAll")]
        [HttpGet]
        public string QueryAll()
        {
            return this.iLabelService.QueryAll();
        }
        [Route("create/{name}")]
        [HttpPost]
        public string Create([FromRoute] string name)
        {
            return this.iLabelService.Create(name);
        }
        [Route("delete/{id}")]
        [HttpDelete]
        public string Delete([FromRoute] int id)
        {
            return this.iLabelService.Delete(id);
        }
    }
}
